-- Table structure for `treasure_box`
-- ----------------------------
DROP TABLE IF EXISTS `treasure_box`;
CREATE TABLE `treasure_box` (
  `box_itemid` int(10) NOT NULL,
  `note` varchar(45) DEFAULT '',
  `itemid` int(10) NOT NULL,
  `note2` varchar(45) DEFAULT '',
  `count` int(10) NOT NULL DEFAULT '1',
  `enchant` int(10) NOT NULL DEFAULT '0',
  `chance` int(10) NOT NULL DEFAULT '0',
  `use_day` int(3) NOT NULL DEFAULT '0' COMMENT '可使用時間',
  `bless_change` int(3) NOT NULL DEFAULT '0',
  `unbless_change` int(3) NOT NULL DEFAULT '0',
  PRIMARY KEY (`box_itemid`,`itemid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of treasure_box
-- ----------------------------

-- ----------------------------
-- Table structure for `weapon`
-- ----------------------------
DROP TABLE IF EXISTS `weapon`;
CREATE TABLE `weapon` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(45) NOT NULL DEFAULT '',
  `unidentified_name_id` varchar(45) NOT NULL DEFAULT '',
  `identified_name_id` varchar(45) NOT NULL DEFAULT '',
  `type` varchar(45) NOT NULL DEFAULT '',
  `material` varchar(45) NOT NULL DEFAULT '',
  `weight` int(10) unsigned NOT NULL DEFAULT '0',
  `invgfx` int(10) unsigned NOT NULL DEFAULT '0',
  `grdgfx` int(10) unsigned NOT NULL DEFAULT '0',
  `itemdesc_id` int(10) unsigned NOT NULL DEFAULT '0',
  `dmg_small` int(10) NOT NULL DEFAULT '0',
  `dmg_large` int(10) NOT NULL DEFAULT '0',
  `range` int(10) NOT NULL DEFAULT '0',
  `safenchant` int(10) NOT NULL DEFAULT '0',
  `use_royal` int(10) unsigned NOT NULL DEFAULT '0',
  `use_knight` int(10) unsigned NOT NULL DEFAULT '0',
  `use_mage` int(10) unsigned NOT NULL DEFAULT '0',
  `use_elf` int(10) unsigned NOT NULL DEFAULT '0',
  `use_darkelf` int(10) unsigned NOT NULL DEFAULT '0',
  `use_dragonknight` int(10) unsigned NOT NULL DEFAULT '0',
  `use_illusionist` int(10) unsigned NOT NULL DEFAULT '0',
  `use_warrior` int(10) NOT NULL,
  `hitmodifier` int(10) NOT NULL DEFAULT '0',
  `dmgmodifier` int(10) NOT NULL DEFAULT '0',
  `add_str` int(10) NOT NULL DEFAULT '0',
  `add_con` int(10) NOT NULL DEFAULT '0',
  `add_dex` int(10) NOT NULL DEFAULT '0',
  `add_int` int(10) NOT NULL DEFAULT '0',
  `add_wis` int(10) NOT NULL DEFAULT '0',
  `add_cha` int(10) NOT NULL DEFAULT '0',
  `add_hp` int(10) NOT NULL DEFAULT '0',
  `add_mp` int(10) NOT NULL DEFAULT '0',
  `add_hpr` int(10) NOT NULL DEFAULT '0',
  `add_mpr` int(10) NOT NULL DEFAULT '0',
  `add_sp` int(10) NOT NULL DEFAULT '0',
  `m_def` int(10) NOT NULL DEFAULT '0',
  `haste_item` int(2) unsigned NOT NULL DEFAULT '0',
  `double_dmg_chance` int(10) unsigned NOT NULL DEFAULT '0',
  `magicdmgmodifier` int(10) NOT NULL DEFAULT '0',
  `canbedmg` int(2) unsigned NOT NULL DEFAULT '0',
  `min_lvl` int(10) unsigned NOT NULL DEFAULT '0',
  `max_lvl` int(10) unsigned NOT NULL DEFAULT '0',
  `bless` int(2) unsigned NOT NULL DEFAULT '1',
  `cant_trade` int(2) unsigned NOT NULL DEFAULT '0',
  `cant_delete` int(2) unsigned NOT NULL DEFAULT '0',
  `max_use_time` int(10) unsigned NOT NULL DEFAULT '0',
  `antiDamageReduction` int(2) NOT NULL DEFAULT '0',
  `stunLevel` int(2) NOT NULL DEFAULT '0',
  PRIMARY KEY (`item_id`)
) ENGINE=MyISAM AUTO_INCREMENT=200311 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of weapon
-- ----------------------------

-- ----------------------------
-- Table structure for `weapon_skill`
-- ----------------------------
DROP TABLE IF EXISTS `weapon_skill`;
CREATE TABLE `weapon_skill` (
  `weapon_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `note` varchar(255) DEFAULT NULL,
  `skill_name` varchar(45) DEFAULT NULL,
  `probability` int(3) unsigned NOT NULL DEFAULT '0',
  `prob_every_enchant` int(2) NOT NULL DEFAULT '0' COMMENT '使用武卷成功+n，魔法發動機率也會+n%',
  `base_damage` int(10) unsigned NOT NULL DEFAULT '0',
  `random_damage` int(10) unsigned NOT NULL DEFAULT '0',
  `area` int(6) NOT NULL DEFAULT '0',
  `effect_id` int(6) unsigned NOT NULL DEFAULT '0',
  `is_target_effect` int(1) unsigned NOT NULL DEFAULT '0',
  `is_arrow` int(1) unsigned NOT NULL DEFAULT '0',
  `attr` int(3) NOT NULL DEFAULT '0',
  `berserkers_rate` double(5,2) NOT NULL DEFAULT '1.20' COMMENT '狂暴術加成倍率',
  `leech_hp` int(5) NOT NULL DEFAULT '0' COMMENT '吸血',
  `leech_mp` int(5) NOT NULL DEFAULT '0' COMMENT '吸魔',
  `leech_every_enchant` int(2) NOT NULL DEFAULT '0' COMMENT '武器每+n 多吸n滴血/魔',
  `chaser_attack_gfxid` int(5) NOT NULL DEFAULT '0' COMMENT '底比斯武器的特效編號',
  `is_caotic` int(1) NOT NULL DEFAULT '0' COMMENT '邪惡值越高，攻擊力越強',
  `is_skill_freeze` int(1) NOT NULL DEFAULT '0' COMMENT '是否凍結目標',
  `is_skill_disease` int(1) NOT NULL DEFAULT '0' COMMENT '是否疾病術目標',
  `is_skill_bind` int(1) NOT NULL DEFAULT '0' COMMENT '是否束縛目標',
  `is_skill_turn_undead` int(1) NOT NULL DEFAULT '0' COMMENT '是否起死回生目標',
  `is_skill_mind_break` int(1) NOT NULL DEFAULT '0' COMMENT '心靈破壞',
  PRIMARY KEY (`weapon_id`)
) ENGINE=MyISAM AUTO_INCREMENT=100206 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of weapon_skill
-- ----------------------------

